sources.content:
global {
  tproxy_port: 12345
  lan_interface: docker0
  wan_interface: auto
  log_level: info
  tcp_check_url: 'http://cp.cloudflare.com'
  check_interval: 30s
}

include {
  nodes.dae
  rules/cn.dae
  rules/lan.dae
  dns.dae
}

group {
  proxy {
    filter: subtag(feed)
    policy: min_moving_avg
  }

  # 影音
  media {
    filter: name(keyword: 'HK')
    policy: min
  }
  ai {
    filter: name(keyword: 'JP')
    policy: min_moving_avg
  }
  office {
    filter: subtag(office)
    policy: fixed(0)
  }
}

include {
  nodes/office.dae
}

subscription {
  feed: 'https://sub.example/a'
  backup: 'https://sub.example/b'
}

node {
  lab: 'socks5://10.0.0.2:1080'
}

dns {
  upstream {
    local: 'udp://223.5.5.5:53'
    remote: 'tcp+udp://1.1.1.1:53'
    backup: 'https://dns.example/dns-query'
  }
  routing {
    request {
      qname(geosite: category-ads-all) -> reject
      qname(geosite:cn) -> local
      qname(suffix: corp.example) -> local
      qname(suffix: lan) -> asis
      fallback: remote
    }
    response {
      upstream(remote) && ip(geoip: private) -> backup
    }
  }
}
